/*
TinyMCE plugin for Google Drive.

Uses the front-end Google API Client (gapi) and Google sign-in (gsi) libraries,
which the TinyMCE configuration loads before initializing the editor.
 */

let accessToken;

async function insertFromGoogleDrive(editor) {
	const googleDriveConfig = {
		appId: editor.settings.googledrive_app_id,
		clientId: editor.settings.googledrive_client_id,
		developerKey: editor.settings.googledrive_developer_key,
		scope: editor.settings.googledrive_scope,
	};

	try {
		await new Promise(function(resolve) {
			gapi.load('client:picker', resolve);
		});

		const client = await google.accounts.oauth2.initTokenClient({
			client_id: googleDriveConfig.clientId,
			scope: googleDriveConfig.scope,
			callback: function(response) {
				onTokenResponse(response, googleDriveConfig, editor);
			},
			error_callback: onTokenResponseError,
		});

		if(!accessToken){
			// show consent screen for user login and authorisation
			client.requestAccessToken({prompt: 'consent'});
		} else {
			// skip consent screen when user has already consented and has a token
			client.requestAccessToken({prompt: ''});
		}
	} catch (error) {
		onTokenResponseError(error);
	}
}

function onTokenResponse(response, googleDriveConfig, editor){
	if (response.error !== undefined) {
		onTokenResponseError(response);
		return;
	}

	accessToken = response.access_token;
	showPicker(googleDriveConfig, editor);
}

function onTokenResponseError(response){
	let messageKey = 'legacyjs.tinymce.googleDrive.signInFailed';
	if (response && response.type === 'popup_failed_to_open') {
		messageKey = 'legacyjs.tinymce.googleDrive.popupBlocked';
	} else if (response && (response.type === 'popup_closed' || response.error === 'access_denied')) {
		messageKey = 'legacyjs.tinymce.googleDrive.authorizationIncomplete';
	}
	apprise(RS.msg(messageKey));
}

function showPicker(googleDriveConfig, editor) {
	let picker;
	const pickerBuilder = new google.picker.PickerBuilder()
		.setDeveloperKey(googleDriveConfig.developerKey)
		.setAppId(googleDriveConfig.appId)
		.setOAuthToken(accessToken)
		.setOrigin(window.location.protocol + '//' + window.location.host)
		.addView(google.picker.ViewId.DOCS)
		.setCallback(function(data) {
			if (data.action === google.picker.Action.ERROR) {
				picker.setVisible(false);
				editor.windowManager.openUrl({
					title: RS.msg('legacyjs.tinymce.googleDrive.pickerTitle'),
					url: pickerBuilder.toUri(),
					width: 1051,
					height: 650,
				});
				return;
			}
			pickerCallback(data);
		});
	picker = pickerBuilder.build();
	picker.setVisible(true);
}

/*
When a Google Drive file is picked, grab some metadata and embed a link in the
rspace document.
 */
function pickerCallback(data) {
	if (data.action === google.picker.Action.PICKED) {
		const doc = data[google.picker.Response.DOCUMENTS][0];
		const googleDriveLinkUrl = doc[google.picker.Document.EMBEDDABLE_URL] || doc[google.picker.Document.URL];

		const name = doc[google.picker.Document.NAME];
		const extension = RS.getFileExtension(name);
		const iconPath = RS.getIconPathForExtension(extension);
		const docId = doc.id;

		const json = {
			id: 'googledrive-' + docId,
			fileStore: 'Google Drive',
			recordURL: googleDriveLinkUrl,
			name: name,
			iconPath: iconPath,
			badgeIconPath: '/images/icons/drive_icon.png'
		};
		RS.insertTemplateIntoTinyMCE('insertedExternalDocumentTemplate', json);
	}
}

tinymce.PluginManager.add('googledrive', function (editor, url) {
	editor.addCommand('cmdGoogleDrive', function () {
		return insertFromGoogleDrive(editor);
	});

	// adds editor button
	editor.ui.registry.addButton('googledrive', {
		tooltip: 'Insert from Google Drive',
		icon: 'google_drive',
		onAction: function () {
			editor.execCommand("cmdGoogleDrive");
		}
	});

	// adds From Google Drive menu item
	editor.ui.registry.addMenuItem('optGoogleDrive', {
		text: 'From Google Drive',
		icon: 'google_drive',
		onAction: function () {
			editor.execCommand("cmdGoogleDrive");
		}
	});

	// adds menu item to Insert menu
  if(!window.insertActions) window.insertActions = new Map();
  window.insertActions.set("optGoogleDrive", {
    text: 'From Google Drive',
    icon: 'google_drive',
    action: () => {
			editor.execCommand("cmdGoogleDrive");
    },
  });

});
